+    struct Close;
+    impl Drop for Close {
+        fn drop(&mut self) {
+            WINDOW.store(false, Ordering::SeqCst);
+        }
+    }
+    let close = Close;
+    let result = run();
+    drop(close);
+    (
+        result,
+        WINDOW_LARGEST.load(Ordering::SeqCst),
+        WINDOW_REQUESTED.load(Ordering::SeqCst),
+    )
+}
